/**
 * Routes that are INTENDED to answer without authentication.
 *
 * Generated by `tests/route-audit.generate.test.ts` and reviewed by hand. Every
 * entry must have a stated reason: an allowlist with unexplained entries is
 * just a list of things nobody looked at.
 *
 * `tests/route-audit.test.ts` fails if any route outside this set answers 2xx
 * with no token, so adding a public endpoint means adding it here deliberately,
 * with a comment. It also fails on entries that no longer correspond to a real
 * route, so the list cannot silently rot.
 *
 * None of these may expose another member's private data, accept a mutation, or
 * reveal whether an account exists.
 */
export const BASELINE_PUBLIC_ROUTES: ReadonlySet<string> = new Set([
  // Liveness probe for the load balancer. No data.
  "GET /health",

  // Capability discovery: tells the client which sign-in buttons to render.
  // Returns booleans derived from whether provider credentials are configured.
  "GET /api/v1/auth/oauth/providers",

  // PKCE web-login progress. Returns ONLY a state string
  // (pending | opened | approved | consumed | denied | expired) and never any
  // account detail, so an unauthenticated caller learns nothing about a user.
  "GET /api/v1/auth/telegram/web-login/:sid/status",

  // Public marketplace browsing: featured gigs, public gig search, the public
  // skill taxonomy, and the public profile surfaces (portfolio, reviews) that
  // the marketing site renders for signed-out visitors.
  "GET /api/v1/featured",
  "GET /api/v1/gigs/search",
  "GET /api/v1/skills",
  "GET /api/v1/skills/categories",
  "GET /api/v1/portfolio/users/:userId/portfolio",
  "GET /api/v1/reviews/users/:userId/reviews",
]);
